// Parse POSIX df output. GNU `df -P` has no type column. BusyBox `df -PT`
// puts the type in the second column. tmpfs and devtmpfs are dropped here
// so the BusyBox fallback matches `df -P -x tmpfs -x devtmpfs`.

// BEGIN_DISK
function parseDf(stdout) {
  var lines = String(stdout || '').split(/\r?\n/);
  var rows = [];
  var i;
  for (i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (!line || /^Filesystem\b/i.test(line)) continue;
    var parts = line.split(/\s+/);
    var capIndex = -1;
    var p;
    for (p = 0; p < parts.length; p++) {
      if (/^\d+%$/.test(parts[p])) capIndex = p;
    }
    if (capIndex < 4) continue;
    var capacity = Number(parts[capIndex].slice(0, -1));
    var available = Number(parts[capIndex - 1]);
    var used = Number(parts[capIndex - 2]);
    var blocks = Number(parts[capIndex - 3]);
    if (!isFinite(capacity) || !isFinite(available) || !isFinite(used) || !isFinite(blocks)) continue;
    var blocksAt = capIndex - 3;
    var fstype = '';
    var filesystem = '';
    if (blocksAt >= 2) {
      fstype = parts[blocksAt - 1];
      filesystem = parts.slice(0, blocksAt - 1).join(' ');
    } else if (blocksAt === 1) {
      filesystem = parts[0];
    } else {
      continue;
    }
    var mount = parts.slice(capIndex + 1).join(' ');
    if (!filesystem || !mount) continue;
    if (/^(tmpfs|devtmpfs)$/i.test(fstype)) continue;
    if (/^(tmpfs|devtmpfs)$/i.test(filesystem)) continue;
    rows.push({
      filesystem: filesystem,
      fstype: fstype || null,
      blocks_1k: blocks,
      used: used,
      available: available,
      capacity_percent: capacity,
      mount: mount,
    });
  }
  return rows;
}

function buildDiskReport(stdout, threshold, exitCode, commandError) {
  var filesystems = parseDf(stdout);
  var over = [];
  var i;
  for (i = 0; i < filesystems.length; i++) {
    if (filesystems[i].capacity_percent >= threshold) over.push(filesystems[i]);
  }
  var ok = !commandError && exitCode === 0 && filesystems.length > 0;
  var message;
  if (commandError) {
    message = 'Disk check failed: ' + commandError;
  } else if (!ok) {
    message = 'Disk check failed: df returned no filesystems.';
  } else if (!over.length) {
    message = 'Disk usage is under ' + threshold + '% on every reported filesystem.';
  } else {
    var lines = ['Disk usage at or above ' + threshold + '%:'];
    for (i = 0; i < over.length; i++) {
      var row = over[i];
      lines.push(row.mount + ' ' + row.capacity_percent + '% (' + row.filesystem + ')');
    }
    message = lines.join('\n');
  }
  return {
    ok: ok,
    threshold: threshold,
    over: over,
    filesystems: filesystems,
    message: message,
  };
}
// END_DISK

const item = $input.first().json || {};
const thresholdNum = Number(item.threshold_percent);
const threshold = isFinite(thresholdNum) ? thresholdNum : 85;
const exitCode = typeof item.exitCode === 'number' ? item.exitCode : (item.error ? 1 : 0);
const report = buildDiskReport(
  String(item.stdout || ''),
  threshold,
  exitCode,
  item.error ? String(item.error) : ''
);
report.source = String(item.source || '');
report.over_count = report.over.length;
report.response_json = JSON.stringify({
  ok: report.ok,
  threshold: report.threshold,
  over: report.over,
  filesystems: report.filesystems,
});
return [{ json: report }];
